properties.description:
Bower events first ingested more than 360 minutes after their event time, or whose
TimeGenerated Azure Monitor rewrote. The replay-safe rules did not evaluate them;
investigate the outage and hunt manually.

properties.query:
// Bower detection-tolerance monitor: events that first arrived later than the
// replay-safe rules' maximum tolerated delay. Those rules never evaluate such events,
// so each result is a detection gap to investigate, not a threat. It also reports
// events whose TimeGenerated Azure Monitor rewrote (event time more than two days old).
let maxDelay = 360m;
let settleDelay = 5m;
let frequency = 60m;
let windowEnd = bin(now() - settleDelay, frequency);
let windowStart = windowEnd - frequency;
let late = BowerSecurity_CL
    | where TimeGenerated >= windowStart - 50h
    | where EventType !in ("collector_health", "collector_canary")
    | extend BowerIngested = ingestion_time()
    | where BowerIngested >= windowStart and BowerIngested < windowEnd
    | extend BowerEventTime = coalesce(todatetime(RawEnvelope.timeGenerated), TimeGenerated)
    | summarize arg_min(BowerIngested, BowerEventTime, TimeGenerated, EventType) by CollectorId, EventId
    | where BowerIngested - BowerEventTime > maxDelay or BowerEventTime != TimeGenerated;
let earlier = BowerSecurity_CL
    | where EventId in ((late | project EventId))
    | where ingestion_time() < windowStart
    | distinct CollectorId, EventId;
late
| join kind=leftanti earlier on CollectorId, EventId
| summarize LateEvents = count(), RewrittenTimes = countif(BowerEventTime != TimeGenerated),
    OldestEvent = min(BowerEventTime), MaxDeliveryDelay = max(BowerIngested - BowerEventTime),
    EventTypes = make_set(EventType, 20)
    by CollectorId
| extend WindowStart = windowStart, WindowEnd = windowEnd

// Bower ASVS pack: password spraying or credential stuffing from one address.
// Application authentication_failure events (BWR-POL-AUTH-FAILURE) from one source address
// against at least `accountThreshold` distinct accounts in one event-time bucket.
// ASVS 5.0 V16.3.1, V6.3.1. Replay-safe via BowerSecurityEventsOfType and BowerDetectionKey.
let accountThreshold = 10;
let bucketSize = 10m;
let settleDelay = 5m;
let frequency = 5m;
let catchUp = 60m;
let maxDelay = 360m;
let ruleKey = "bower-asvs-password-spray:default";
let windowEnd = bin(now() - settleDelay, frequency);
let catchUpStart = windowEnd - catchUp;
let horizon = bin(catchUpStart - maxDelay, bucketSize);
let alerted = SecurityAlert
    | where ProviderName == "ASI Scheduled Alerts"
    | extend BowerDetectionKey = tostring(todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"])).BowerDetectionKey[0])
    | where BowerDetectionKey startswith strcat(ruleKey, "|")
    | distinct BowerDetectionKey;
let candidates = materialize(BowerSecurityEventsOfType(dynamic(["authentication_failure", "authentication_success"]))
    | where ApplicationName !in ("windows-security", "ssh-gateway", "linux-sshd")
    | where isnotempty(SourceIpAddress) and isnotempty(coalesce(ActorUsername, ActorUserId))
    | where BowerEventTime >= horizon and BowerFirstIngested < windowEnd
    | where BowerFirstIngested - BowerEventTime <= maxDelay
    | extend Account = coalesce(ActorUsername, ActorUserId), BucketStart = bin(BowerEventTime, bucketSize));
candidates
| summarize Failures = countif(EventType == "authentication_failure"),
    DistinctAccounts = count_distinctif(Account, EventType == "authentication_failure"),
    SuccessesAfterFailures = countif(EventType == "authentication_success"),
    FailedAccounts = make_set_if(Account, EventType == "authentication_failure", 20),
    Applications = make_set(ApplicationName, 10), Collectors = make_set(CollectorId, 10),
    LastIngested = max(BowerFirstIngested), FirstEvent = min(BowerEventTime), LastEvent = max(BowerEventTime)
    by SourceIpAddress, BucketStart
| where DistinctAccounts >= accountThreshold
| where LastIngested >= catchUpStart
| extend BowerDetectionKey = strcat(ruleKey, "|", SourceIpAddress, "|", tostring(BucketStart))
| where BowerDetectionKey !in (alerted)
| project BowerDetectionKey, SourceIpAddress, BucketStart, Failures, DistinctAccounts, SuccessesAfterFailures,
    FailedAccounts, Applications, Collectors, FirstEvent, LastEvent, EvaluatedAt = now()

// Bower ASVS pack: privilege, role or permission change.
// One alert per change: role_membership_changed (BWR-POL-ROLE-MEMBERSHIP), and
// permission_changed or admin_action with action admin.grant (BWR-PACK-ASVS-ADMIN).
// ASVS 5.0 V16.3.3, V8.3.2; ISM-1650. Replay-safe: alerts once per (CollectorId, EventId).
let settleDelay = 5m;
let frequency = 5m;
let catchUp = 60m;
let maxDelay = 360m;
let ruleKey = "bower-asvs-privilege-change:default";
let windowEnd = bin(now() - settleDelay, frequency);
let catchUpStart = windowEnd - catchUp;
let alerted = SecurityAlert
    | where ProviderName == "ASI Scheduled Alerts"
    | extend BowerDetectionKey = tostring(todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"])).BowerDetectionKey[0])
    | where BowerDetectionKey startswith strcat(ruleKey, "|")
    | distinct BowerDetectionKey;
BowerSecurityEventsOfType(dynamic(["role_membership_changed", "permission_changed", "admin_action"]))
| where EventResult == "success"
| where EventType != "admin_action" or EventAction == "admin.grant"
| where BowerFirstIngested >= catchUpStart and BowerFirstIngested < windowEnd
| where BowerFirstIngested - BowerEventTime <= maxDelay
| extend BowerDetectionKey = strcat(ruleKey, "|", CollectorId, "|", EventId)
| where BowerDetectionKey !in (alerted)
| project BowerDetectionKey, BowerEventTime, ApplicationName, ApplicationEnvironment, EventType, EventAction,
    ActorUserId, SourceIpAddress, CorrelationId, CollectorId, EventId, EvaluatedAt = now()

// Bower ASVS pack: privileged or configuration action outside business hours.
// admin_action, configuration_changed, permission_changed and role_membership_changed
// events whose event time falls outside `businessStart`-`businessEnd` on a weekday, or at any
// time on a weekend, in `timeZone` (IANA name, default Australia/Sydney).
// ASVS 5.0 V16.3.3. Replay-safe: once per event.
let timeZone = "Australia/Sydney";
let businessStart = 7;
let businessEnd = 19;
let settleDelay = 5m;
let frequency = 5m;
let catchUp = 60m;
let maxDelay = 360m;
let ruleKey = "bower-asvs-admin-after-hours:default";
let windowEnd = bin(now() - settleDelay, frequency);
let catchUpStart = windowEnd - catchUp;
let alerted = SecurityAlert
    | where ProviderName == "ASI Scheduled Alerts"
    | extend BowerDetectionKey = tostring(todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"])).BowerDetectionKey[0])
    | where BowerDetectionKey startswith strcat(ruleKey, "|")
    | distinct BowerDetectionKey;
BowerSecurityEventsOfType(dynamic(["admin_action", "configuration_changed", "permission_changed", "role_membership_changed"]))
| where EventResult == "success"
| where BowerFirstIngested >= catchUpStart and BowerFirstIngested < windowEnd
| where BowerFirstIngested - BowerEventTime <= maxDelay
| extend LocalTime = datetime_utc_to_local(BowerEventTime, timeZone)
| extend LocalHour = hourofday(LocalTime), LocalDay = toint(dayofweek(LocalTime) / 1d)
| where LocalDay in (0, 6) or LocalHour < businessStart or LocalHour >= businessEnd
| extend BowerDetectionKey = strcat(ruleKey, "|", CollectorId, "|", EventId)
| where BowerDetectionKey !in (alerted)
| project BowerDetectionKey, BowerEventTime, LocalTime, TimeZone = timeZone, ApplicationName, EventType, EventAction,
    ActorUserId, SourceIpAddress, CorrelationId, CollectorId, EventId, EvaluatedAt = now()

// Bower ASVS pack: mass export or bulk sensitive reads by one user.
// sensitive_data_exported (BWR-POL-SENSITIVE-EXPORT) and sensitive_data_accessed
// (BWR-PACK-ASVS-SENSITIVE-DATA) records summed per user and application in one event-time
// bucket. ASVS 5.0 V16.3.2, V2.4.1. Replay-safe: once per (user, app, bucket).
let recordThreshold = 10000;
let exportThreshold = 5;
let bucketSize = 60m;
let settleDelay = 5m;
let frequency = 5m;
let catchUp = 60m;
let maxDelay = 360m;
let ruleKey = "bower-asvs-mass-export:default";
let windowEnd = bin(now() - settleDelay, frequency);
let catchUpStart = windowEnd - catchUp;
let horizon = bin(catchUpStart - maxDelay, bucketSize);
let alerted = SecurityAlert
    | where ProviderName == "ASI Scheduled Alerts"
    | extend BowerDetectionKey = tostring(todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"])).BowerDetectionKey[0])
    | where BowerDetectionKey startswith strcat(ruleKey, "|")
    | distinct BowerDetectionKey;
let counts = BowerSecurity_CL
    | where EventType in ("sensitive_data_exported", "sensitive_data_accessed")
    | summarize RecordCount = take_any(tolong(Attributes.recordCount)) by CollectorId, EventId;
BowerSecurityEventsOfType(dynamic(["sensitive_data_exported", "sensitive_data_accessed"]))
| where EventResult == "success" and isnotempty(ActorUserId)
| where BowerEventTime >= horizon and BowerFirstIngested < windowEnd
| where BowerFirstIngested - BowerEventTime <= maxDelay
| join kind=leftouter counts on CollectorId, EventId
| extend BucketStart = bin(BowerEventTime, bucketSize)
| summarize Records = sum(coalesce(RecordCount, 1)), Exports = countif(EventType == "sensitive_data_exported"),
    Events = count(), LastIngested = max(BowerFirstIngested), FirstEvent = min(BowerEventTime), LastEvent = max(BowerEventTime),
    Collectors = make_set(CollectorId, 10)
    by ActorUserId, ApplicationName, BucketStart
| where Records >= recordThreshold or Exports >= exportThreshold
| where LastIngested >= catchUpStart
| extend BowerDetectionKey = strcat(ruleKey, "|", ApplicationName, "|", ActorUserId, "|", tostring(BucketStart))
| where BowerDetectionKey !in (alerted)
| project BowerDetectionKey, ActorUserId, ApplicationName, BucketStart, Records, Exports, Events, Collectors,
    FirstEvent, LastEvent, EvaluatedAt = now()

// Bower ASVS pack: an application stopped sending security events.
// Applications that sent security events in the 7-day baseline and none in the last 60m.
// ASVS 5.0 V16.4.3; ISM-1405, ISM-1906. One alert per application, environment and silence start.
let silence = 60m;
let baseline = 7d;
let minimumBaselineEvents = 20;
let ruleKey = "bower-asvs-log-silence:default";
let alerted = SecurityAlert
    | where ProviderName == "ASI Scheduled Alerts"
    | extend BowerDetectionKey = tostring(todynamic(tostring(todynamic(ExtendedProperties)["Custom Details"])).BowerDetectionKey[0])
    | where BowerDetectionKey startswith strcat(ruleKey, "|")
    | distinct BowerDetectionKey;
BowerSecurity_CL
| where TimeGenerated > ago(baseline)
| where EventType !in ("collector_health", "collector_canary", "telemetry_aggregation_summary")
| summarize LastSeen = max(TimeGenerated), BaselineEvents = count(), Collectors = make_set(CollectorId, 10)
    by ApplicationName, ApplicationEnvironment
| where BaselineEvents >= minimumBaselineEvents
| where LastSeen < ago(silence)
| extend BowerDetectionKey = strcat(ruleKey, "|", ApplicationName, "|", ApplicationEnvironment, "|", tostring(LastSeen))
| where BowerDetectionKey !in (alerted)
| project BowerDetectionKey, ApplicationName, ApplicationEnvironment, LastSeen,
    SilentMinutes = datetime_diff("minute", now(), LastSeen), BaselineEvents, Collectors, EvaluatedAt = now()

// Bower: collector health record missing (collector down, host down, or delivery to Sentinel failing).
// One row per collector whose newest collector_health record was ingested more than
// 15 minutes ago, or (when listed in the expected set) never arrived in the window.
let missingAfter = 15m;
let expected = print CollectorId = dynamic([])
    | mv-expand CollectorId to typeof(string)
    | where isnotempty(CollectorId);
let seen = BowerSecurity_CL
    | where EventType == "collector_health" and isnotempty(CollectorId)
    | summarize LastIngested = max(ingestion_time()), LastRecordAt = max(TimeGenerated) by CollectorId;
union
    (expected | join kind=leftanti seen on CollectorId | extend LastIngested = datetime(null), LastRecordAt = datetime(null)),
    seen
| where isnull(LastIngested) or LastIngested < ago(missingAfter)
| extend MinutesSinceLastRecord = iff(isnull(LastIngested), real(null), round(datetime_diff('second', now(), LastIngested) / 60.0, 1))
| project CollectorId, LastIngested, LastRecordAt, MinutesSinceLastRecord
| extend LastIngestedText = tostring(LastIngested), MinutesText = tostring(MinutesSinceLastRecord)

// Bower: source silent at the destination. Independent of collector logic and health records:
// one row per collector and application/environment whose newest security event (not a health
// record or canary) was ingested more than its allowance ago, while it sent within the window.
let defaultMinutes = 60;
let overrides = print Rule = dynamic([])
    | mv-expand Rule
    | where isnotempty(Rule)
    | project ApplicationName = tostring(Rule.application), ApplicationEnvironment = tostring(Rule.environment),
        AllowedMinutes = toint(Rule.maximumSilenceMinutes);
BowerSecurity_CL
| where EventType !in ("collector_health", "collector_canary")
| where isnotempty(CollectorId) and isnotempty(ApplicationName)
| where isempty(tostring(Labels.bowerReplay))
| summarize LastIngested = max(ingestion_time()), LastEventAt = max(TimeGenerated) by CollectorId, ApplicationName, ApplicationEnvironment
| join kind=leftouter overrides on ApplicationName, ApplicationEnvironment
| extend AllowedMinutes = coalesce(AllowedMinutes, defaultMinutes)
| extend SilentMinutes = round(datetime_diff('second', now(), LastIngested) / 60.0, 1)
| where SilentMinutes > AllowedMinutes
| project CollectorId, Source = strcat(ApplicationName, "/", ApplicationEnvironment), LastIngested, LastEventAt, SilentMinutes, AllowedMinutes
| extend LastIngestedText = tostring(LastIngested), MinutesText = tostring(SilentMinutes)
